"use client";

import { useState, useEffect } from "react";
import { useParams } from "next/navigation";
import { PlayCircle, Check, X, TrendingUp, AlertTriangle } from "lucide-react";
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from "recharts";

export default function ContractLearningPage() {
  const params = useParams();
  const contractId = params?.id as string || "1";

  const [recommendations, setRecommendations] = useState<unknown[]>([]);
  const [stats, setStats] = useState<unknown[]>([]);
  const [loading, setLoading] = useState(true);
  const [triggering, setTriggering] = useState(false);

  const fetchData = React.useCallback(async () => {
    try {
      const [recsRes, statsRes] = await Promise.all([
        fetch(`http://localhost:8000/api/v1/learning/contracts/${contractId}/recommendations`),
        fetch(`http://localhost:8000/api/v1/learning/contracts/${contractId}/statistics`)
      ]);
      const recs = await recsRes.json();
      const st = await statsRes.json();
      setRecommendations(Array.isArray(recs) ? recs : []);
      setStats(Array.isArray(st) ? st : []);
    } catch (e) {
      console.error("Failed to fetch learning data", e);
    } finally {
      setLoading(false);
    }
  }, [contractId]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const triggerLearning = async () => {
    setTriggering(true);
    try {
      await fetch(`http://localhost:8000/api/v1/learning/contracts/${contractId}/trigger`, {
        method: "POST"
      });
      alert("Learning cycle queued! Please refresh in a moment.");
    } catch (e) {
      alert("Failed to trigger learning");
    } finally {
      setTriggering(false);
    }
  };

  const approveRecommendation = async (recId: number) => {
    await fetch(`http://localhost:8000/api/v1/learning/contracts/${contractId}/recommendations/${recId}/approve`, {
      method: "POST"
    });
    fetchData();
  };

  const rejectRecommendation = async (recId: number) => {
    await fetch(`http://localhost:8000/api/v1/learning/contracts/${contractId}/recommendations/${recId}/reject?reason=UserRejected`, {
      method: "POST"
    });
    fetchData();
  };

  if (loading) {
    return <div className="p-8 text-slate-500">Loading AI Learning Engine...</div>;
  }

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 bg-slate-50 min-h-screen">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">AI Contract Learning Engine</h1>
          <p className="text-slate-500 text-sm mt-1">Autonomous evaluation of rule stability based on historical validation runs.</p>
        </div>
        <button 
          onClick={triggerLearning}
          disabled={triggering}
          className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-indigo-700 flex items-center space-x-2 disabled:opacity-50"
        >
          <PlayCircle className="w-4 h-4" />
          <span>{triggering ? "Running..." : "Run Learning Cycle"}</span>
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
            <h2 className="text-lg font-semibold text-slate-900 mb-4 flex items-center gap-2">
              <TrendingUp className="w-5 h-5 text-indigo-500" />
              Recommendation Queue
            </h2>
            {recommendations.length === 0 ? (
              <div className="text-center py-8 text-slate-500 bg-slate-50 rounded-lg border border-dashed border-slate-300">
                No new recommendations for this contract. It is perfectly optimized!
              </div>
            ) : (
              <div className="space-y-4">
                {recommendations.map((rec) => (
                  <div key={rec.id} className="border border-indigo-100 bg-indigo-50/30 rounded-lg p-5">
                    <div className="flex justify-between items-start">
                      <div>
                        <div className="flex items-center gap-3">
                          <h3 className="font-medium text-slate-900">Update Rule: {rec.rule_name}</h3>
                          <span className="px-2 py-0.5 rounded-full text-xs font-semibold bg-green-100 text-green-700">
                            {rec.confidence}% Confidence
                          </span>
                        </div>
                        <p className="text-sm text-slate-600 mt-2">{rec.explanation}</p>
                        
                        <div className="mt-4 flex items-center space-x-6 text-sm">
                          <div>
                            <span className="text-slate-500 block text-xs uppercase tracking-wider mb-1">Old Threshold</span>
                            <span className="font-mono bg-slate-100 px-2 py-1 rounded line-through text-slate-500">{rec.old_threshold}</span>
                          </div>
                          <div className="text-slate-400">→</div>
                          <div>
                            <span className="text-indigo-600 block text-xs uppercase tracking-wider font-semibold mb-1">New Recommendation</span>
                            <span className="font-mono bg-indigo-100 text-indigo-700 px-2 py-1 rounded font-medium">{rec.new_threshold}</span>
                          </div>
                        </div>
                      </div>
                      
                      <div className="flex flex-col space-y-2 ml-4">
                        <button onClick={() => approveRecommendation(rec.id)} className="bg-green-600 hover:bg-green-700 text-white px-3 py-1.5 rounded-md text-sm font-medium flex items-center justify-center gap-1 transition-colors">
                          <Check className="w-4 h-4" /> Approve
                        </button>
                        <button onClick={() => rejectRecommendation(rec.id)} className="bg-white hover:bg-slate-50 border border-slate-200 text-slate-600 px-3 py-1.5 rounded-md text-sm font-medium flex items-center justify-center gap-1 transition-colors">
                          <X className="w-4 h-4" /> Reject
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
          
          <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
            <h2 className="text-lg font-semibold text-slate-900 mb-4">Metric Drift Dashboard</h2>
            <div className="h-64 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={stats.slice().reverse()}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E2E8F0" />
                  <XAxis dataKey="calculated_at" hide />
                  <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748B', fontSize: 12}} />
                  <Tooltip />
                  <Area type="monotone" dataKey="mean" stroke="#6366F1" fill="#EEF2FF" strokeWidth={2} />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
            <h3 className="text-sm font-semibold text-slate-900 uppercase tracking-wider flex items-center gap-2 mb-4">
              <AlertTriangle className="w-4 h-4 text-amber-500" />
              Latest Statistics
            </h3>
            {stats.length === 0 ? (
              <p className="text-sm text-slate-500">No learning history available.</p>
            ) : (
              <div className="space-y-3">
                {stats.slice(0, 5).map((s, i) => (
                  <div key={i} className="flex justify-between items-center text-sm border-b border-slate-100 pb-2 last:border-0">
                    <span className="text-slate-600">{s.metric_name}</span>
                    <span className="font-mono font-medium text-slate-900">μ={s.mean?.toFixed(2)} σ={s.std?.toFixed(2)}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { useContract360 } from "@/api/contracts";
import { 
  ArrowLeft, Activity, ShieldAlert, CheckCircle, 
  XCircle, AlertTriangle, ShieldCheck, Database, 
  TerminalSquare, PlayCircle, Settings
} from "lucide-react";
import { format } from "date-fns";
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer, Legend
} from "recharts";
import { ReactFlow, Controls, Background } from "@xyflow/react";
import "@xyflow/react/dist/style.css";

export default function Contract360Page() {
  const params = useParams();
  const router = useRouter();
  const contractId = Number(params.id);
  const [activeTab, setActiveTab] = useState("overview");

  const { data: contractData, isLoading, isError } = useContract360(contractId);

  if (isLoading) {
    return (
      <div className="p-8 space-y-6 animate-pulse">
        <div className="h-10 bg-muted rounded w-48" />
        <div className="h-[200px] bg-muted rounded w-full" />
        <div className="h-[400px] bg-muted rounded w-full" />
      </div>
    );
  }

  if (isError || !contractData) {
    return (
      <div className="flex flex-col items-center justify-center h-full space-y-4 pt-20">
        <XCircle className="h-16 w-16 text-red-500" />
        <h2 className="text-2xl font-bold">Failed to load contract</h2>
        <button onClick={() => router.back()} className="px-4 py-2 bg-blue-600 text-white rounded">Go Back</button>
      </div>
    );
  }

  const {
    overview, rules, raw_yaml, validation_timeline, execution_history, 
    affected_assets, lineage, incidents, alerts
  } = contractData;

  const flowNodes = lineage.nodes.map((n: any, idx: number) => ({
    id: n.id,
    position: { x: idx * 250, y: 100 },
    data: { label: `${n.database}.${n.schema_name}.${n.label}` },
    style: { border: "1px solid #444", padding: 10, borderRadius: 5, background: "#111", color: "#fff" }
  }));
  const flowEdges = lineage.edges.map((e: any) => ({
    id: e.id, source: e.source, target: e.target, animated: true, style: { stroke: '#888' }
  }));

  const tabs = [
    { id: "overview", label: "Overview" },
    { id: "rules", label: "Rules & YAML" },
    { id: "history", label: "Execution History" },
    { id: "lineage", label: "Lineage & Assets" },
    { id: "incidents", label: "Incidents & Alerts" }
  ];

  return (
    <div className="flex-1 space-y-6 p-8 pb-16 h-full overflow-y-auto w-full bg-background text-foreground">
      {/* HEADER SECTION */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <button className="p-2 border border-border rounded-md hover:bg-muted" onClick={() => router.push("/contracts")}>
            <ArrowLeft className="h-4 w-4" />
          </button>
          <div>
            <h1 className="text-3xl font-bold tracking-tight">{overview.name}</h1>
            <p className="text-muted-foreground flex items-center gap-2 mt-1 text-sm">
              {overview.status === "ACTIVE" ? <ShieldCheck className="h-4 w-4 text-green-500" /> : <ShieldAlert className="h-4 w-4 text-yellow-500" />}
              {overview.status} • v{overview.version} • Owner: {overview.owner?.name || "Unassigned"}
            </p>
          </div>
        </div>
        <div className="flex items-center space-x-2">
          <button className="flex items-center px-4 py-2 border border-border rounded-md hover:bg-muted text-sm font-medium">
            <Settings className="h-4 w-4 mr-2" /> Edit
          </button>
          <button className="flex items-center px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-md text-sm font-medium transition-colors">
            <PlayCircle className="h-4 w-4 mr-2" /> Run Now
          </button>
        </div>
      </div>

      {/* OVERVIEW CARDS */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        <div className="glass-card p-5 rounded-lg border border-border">
          <div className="flex items-center justify-between mb-2">
            <h3 className="text-sm font-medium text-foreground">Health Score</h3>
            <Activity className="h-4 w-4 text-muted-foreground" />
          </div>
          <div className="text-2xl font-bold">{overview.health_score.toFixed(1)}%</div>
          <p className="text-xs text-muted-foreground mt-1">Based on last 100 runs</p>
        </div>
        <div className="glass-card p-5 rounded-lg border border-border">
          <div className="flex items-center justify-between mb-2">
            <h3 className="text-sm font-medium text-foreground">Success Rate</h3>
            <CheckCircle className="h-4 w-4 text-green-500" />
          </div>
          <div className="text-2xl font-bold">{overview.success_rate.toFixed(1)}%</div>
        </div>
        <div className="glass-card p-5 rounded-lg border border-border">
          <div className="flex items-center justify-between mb-2">
            <h3 className="text-sm font-medium text-foreground">Open Incidents</h3>
            <AlertTriangle className="h-4 w-4 text-red-500" />
          </div>
          <div className="text-2xl font-bold">{overview.incident_count}</div>
        </div>
        <div className="glass-card p-5 rounded-lg border border-border">
          <div className="flex items-center justify-between mb-2">
            <h3 className="text-sm font-medium text-foreground">AI Score</h3>
            <TerminalSquare className="h-4 w-4 text-purple-500" />
          </div>
          <div className="text-2xl font-bold">{overview.ai_score.toFixed(1)}</div>
          <p className="text-xs text-muted-foreground mt-1">Rule coverage optimization</p>
        </div>
      </div>

      {/* TABS */}
      <div className="space-y-4 mt-6">
        <div className="flex space-x-1 border-b border-border overflow-x-auto">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`px-4 py-2 text-sm font-medium whitespace-nowrap transition-colors border-b-2 ${
                activeTab === tab.id ? "border-blue-500 text-blue-400" : "border-transparent text-muted-foreground hover:text-foreground"
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* OVERVIEW TAB */}
        {activeTab === "overview" && (
          <div className="glass-card rounded-lg border border-border p-5">
            <h3 className="text-lg font-medium mb-1">Validation Timeline</h3>
            <p className="text-sm text-muted-foreground mb-6">Pass/Fail trends over recent executions</p>
            <div className="h-[300px]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={validation_timeline}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#333" />
                  <XAxis dataKey="date" stroke="#888" />
                  <YAxis stroke="#888" />
                  <RechartsTooltip contentStyle={{ backgroundColor: '#111', borderColor: '#333' }} />
                  <Legend />
                  <Bar dataKey="pass_count" name="Passed" fill="#22c55e" radius={[4, 4, 0, 0]} />
                  <Bar dataKey="fail_count" name="Failed" fill="#ef4444" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}

        {/* RULES & YAML TAB */}
        {activeTab === "rules" && (
          <div className="grid md:grid-cols-2 gap-4">
            <div className="glass-card rounded-lg border border-border p-5">
              <h3 className="text-lg font-medium mb-4">Active Rules</h3>
              <div className="space-y-4">
                {rules.length === 0 && <p className="text-sm text-muted-foreground">No explicit rules parsed.</p>}
                {rules.map((rule: any, i: number) => (
                  <div key={i} className="flex items-center justify-between p-3 border border-border bg-muted/20 rounded-lg">
                    <div>
                      <p className="font-medium text-sm text-foreground">{rule.rule_type}</p>
                      <p className="text-xs text-muted-foreground">{rule.description}</p>
                    </div>
                    <span className="text-xs font-mono bg-muted px-2 py-1 rounded text-foreground">{rule.config?.column}</span>
                  </div>
                ))}
              </div>
            </div>
            <div className="glass-card rounded-lg border border-border p-5">
              <h3 className="text-lg font-medium mb-4">Raw Configuration (YAML)</h3>
              <pre className="p-4 bg-zinc-950 border border-border text-zinc-300 rounded-lg text-sm overflow-x-auto h-[400px]">
                <code>{raw_yaml || "# No YAML available"}</code>
              </pre>
            </div>
          </div>
        )}

        {/* EXECUTION HISTORY TAB */}
        {activeTab === "history" && (
          <div className="glass-card rounded-lg border border-border overflow-hidden">
            <div className="p-5 border-b border-border">
              <h3 className="text-lg font-medium">Recent Runs</h3>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm text-left">
                <thead className="bg-muted text-muted-foreground border-b border-border">
                  <tr>
                    <th className="p-4 font-medium">Run ID</th>
                    <th className="p-4 font-medium">Status</th>
                    <th className="p-4 font-medium">Started</th>
                    <th className="p-4 font-medium">Duration</th>
                    <th className="p-4 font-medium">Violations</th>
                  </tr>
                </thead>
                <tbody>
                  {execution_history.length === 0 && (
                    <tr><td colSpan={5} className="p-4 text-center text-muted-foreground">No runs found</td></tr>
                  )}
                  {execution_history.map((run: any) => (
                    <tr key={run.id} className="border-b border-border hover:bg-muted/30 transition-colors">
                      <td className="p-4 font-medium text-foreground">{run.run_id}</td>
                      <td className="p-4">
                        <span className={`px-2 py-1 rounded text-xs font-medium ${
                          run.status === "PASSED" ? "bg-green-500/20 text-green-400" : "bg-red-500/20 text-red-400"
                        }`}>
                          {run.status}
                        </span>
                      </td>
                      <td className="p-4 text-muted-foreground">{format(new Date(run.started_at), "PPp")}</td>
                      <td className="p-4 text-muted-foreground">{run.duration_ms} ms</td>
                      <td className="p-4 text-foreground">{run.violations}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* LINEAGE & ASSETS */}
        {activeTab === "lineage" && (
          <div className="grid lg:grid-cols-3 gap-4">
            <div className="lg:col-span-1 glass-card rounded-lg border border-border p-5">
              <h3 className="text-lg font-medium mb-4">Monitored Assets</h3>
              <div className="space-y-4">
                {affected_assets.length === 0 && <p className="text-sm text-muted-foreground">No assets found.</p>}
                {affected_assets.map((asset: any) => (
                  <div key={asset.id} className="p-4 border border-border bg-muted/20 rounded-lg flex items-center space-x-4">
                    <Database className="h-8 w-8 text-blue-500" />
                    <div>
                      <p className="font-semibold text-sm text-foreground">{asset.table_name}</p>
                      <p className="text-xs text-muted-foreground">{asset.database}.{asset.schema_name}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
            <div className="lg:col-span-2 glass-card rounded-lg border border-border p-5">
              <h3 className="text-lg font-medium mb-4">Lineage Graph</h3>
              <div className="h-[400px] border border-border rounded-lg bg-black/20">
                {flowNodes.length > 0 ? (
                  <ReactFlow nodes={flowNodes} edges={flowEdges} fitView colorMode="dark">
                    <Background color="#333" />
                    <Controls />
                  </ReactFlow>
                ) : (
                  <div className="flex h-full items-center justify-center text-muted-foreground">
                    No lineage data available
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
        
        {/* INCIDENTS */}
        {activeTab === "incidents" && (
          <div className="grid md:grid-cols-2 gap-4">
            <div className="glass-card rounded-lg border border-border p-5">
              <h3 className="text-lg font-medium mb-4">Incidents</h3>
              {incidents.length === 0 ? <p className="text-sm text-muted-foreground">No open incidents.</p> : (
                <div className="space-y-4">
                  {incidents.map((inc: any) => (
                    <div key={inc.id} className="p-3 border border-border bg-muted/20 rounded-lg border-l-4 border-l-red-500">
                      <div className="flex justify-between items-center mb-1">
                        <span className="font-semibold text-sm text-foreground">INC-{inc.id}</span>
                        <span className="text-xs font-medium px-2 py-0.5 rounded border border-border text-foreground">{inc.status}</span>
                      </div>
                      <p className="text-xs text-muted-foreground">{format(new Date(inc.created_at), "PPp")}</p>
                    </div>
                  ))}
                </div>
              )}
            </div>
            <div className="glass-card rounded-lg border border-border p-5">
              <h3 className="text-lg font-medium mb-4">Alert Deliveries</h3>
              {alerts.length === 0 ? <p className="text-sm text-muted-foreground">No alerts sent recently.</p> : (
                <div className="space-y-3">
                  {alerts.map((al: any) => (
                    <div key={al.id} className="flex justify-between p-3 border border-border bg-muted/20 rounded-lg text-sm">
                      <span className="text-foreground">{al.channel}</span>
                      <span className={al.status === "DELIVERED" ? "text-green-400 font-medium" : "text-yellow-400 font-medium"}>{al.status}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import { Panel, PanelGroup, PanelResizeHandle } from 'react-resizable-panels';
import { useHotkeys } from 'react-hotkeys-hook';
import { toast } from 'sonner';
import { History, Save, Send, Check, Play, Archive, Pause } from 'lucide-react';

import { useContractStore, ContractStatus } from '@/store/useContractStore';
import { VisualBuilder } from '@/components/contracts/VisualBuilder';
import { YamlEditor } from '@/components/contracts/YamlEditor';
import { DiffViewer } from '@/components/contracts/DiffViewer';
import { LivePreviewPanel } from '@/components/contracts/LivePreviewPanel';
import { TemplateMarketplace } from '@/components/contracts/TemplateMarketplace';
import { VersionHistoryPanel } from '@/components/contracts/VersionHistoryPanel';
import { ReviewDeployModal } from '@/components/contracts/ReviewDeployModal';

export default function ContractAuthoringPage() {
  const router = useRouter();
  const { 
    contract, yaml, setYaml, setContract, isDirty, isYamlValid, 
    markSaved, versions, selectedVersion 
  } = useContractStore();
  
  const [showTemplates, setShowTemplates] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [isDeploying, setIsDeploying] = useState(false);
  const [showReviewModal, setShowReviewModal] = useState(false);

  const handleSaveDraft = () => {
    if (!isYamlValid) {
      toast.error('Cannot save draft: YAML syntax is invalid');
      return;
    }
    markSaved();
    toast.success('Draft saved and version created');
  };

  // Keyboard Shortcuts
  useHotkeys('ctrl+s, cmd+s', (e) => {
    e.preventDefault();
    handleSaveDraft();
  }, { enableOnFormTags: true });

  const handleStatusChange = (newStatus: ContractStatus) => {
    setContract(prev => ({ ...prev, status: newStatus }));
    toast.success(`Contract moved to ${newStatus}`);
    markSaved();
  };

  const executeDeploy = () => {
    setIsDeploying(true);
    setTimeout(() => {
      handleStatusChange('published');
      setIsDeploying(false);
      setShowReviewModal(false);
    }, 1000);
  };

  const getStatusBadge = (status: ContractStatus) => {
    const map = {
      draft: 'bg-gray-500/10 text-gray-400 border-gray-500/20',
      review: 'bg-yellow-500/10 text-yellow-500 border-yellow-500/20',
      approved: 'bg-blue-500/10 text-blue-400 border-blue-500/20',
      published: 'bg-green-500/10 text-green-400 border-green-500/20',
      paused: 'bg-orange-500/10 text-orange-400 border-orange-500/20',
      deprecated: 'bg-red-500/10 text-red-400 border-red-500/20',
      archived: 'bg-neutral-500/10 text-neutral-400 border-neutral-500/20',
    };
    return (
      <span className={`px-2 py-0.5 rounded text-xs font-bold border uppercase tracking-wider ${map[status] || map.draft}`}>
        {status}
      </span>
    );
  };

  // Determine what to show in the right panel
  const selectedVersionObj = versions.find(v => v.version === selectedVersion);
  const showDiffViewer = selectedVersionObj !== undefined;

  return (
    <div className="h-screen flex flex-col overflow-hidden bg-background">
      {/* Header */}
      <header className="h-14 border-b border-border flex items-center justify-between px-4 shrink-0 bg-card">
        <div className="flex items-center gap-4">
          <button onClick={() => router.back()} className="text-muted-foreground hover:text-foreground">
            &larr; Back
          </button>
          <div className="h-4 w-px bg-border" />
          <h1 className="font-bold text-foreground flex items-center gap-3">
            {contract.contract_name || 'Untitled Contract'}
            {getStatusBadge(contract.status)}
            {isDirty && <span className="text-xs text-yellow-500 font-normal">● Unsaved Changes</span>}
          </h1>
        </div>
        
        <div className="flex items-center gap-3">
          <button 
            onClick={() => { setShowHistory(!showHistory); setShowTemplates(false); }}
            className={`px-3 py-1.5 text-sm font-medium border rounded transition flex items-center gap-2 ${showHistory ? 'bg-blue-500/10 border-blue-500/30 text-blue-400' : 'border-border hover:bg-muted'}`}
          >
            <History className="w-4 h-4" />
            History
          </button>
          
          <button 
            onClick={handleSaveDraft}
            className="px-3 py-1.5 text-sm font-medium border border-border rounded hover:bg-muted transition flex items-center gap-2"
          >
            <Save className="w-4 h-4 text-muted-foreground" />
            Save Draft
          </button>

          <div className="h-4 w-px bg-border mx-1" />

          {/* Dynamic Lifecycle Actions */}
          {contract.status === 'draft' && (
            <button 
              onClick={() => handleStatusChange('review')}
              disabled={!isYamlValid}
              className="px-4 py-1.5 text-sm font-medium bg-blue-600 hover:bg-blue-700 text-white rounded transition disabled:opacity-50 flex items-center gap-2"
            >
              <Send className="w-4 h-4" />
              Request Review
            </button>
          )}
          
          {contract.status === 'review' && (
            <>
              <button 
                onClick={() => handleStatusChange('draft')}
                className="px-3 py-1.5 text-sm font-medium border border-border rounded hover:bg-muted transition"
              >
                Cancel Review
              </button>
              <button 
                onClick={() => handleStatusChange('approved')}
                className="px-4 py-1.5 text-sm font-medium bg-green-600 hover:bg-green-700 text-white rounded transition flex items-center gap-2"
              >
                <Check className="w-4 h-4" />
                Approve Contract
              </button>
            </>
          )}

          {contract.status === 'approved' && (
            <button 
              onClick={() => setShowReviewModal(true)}
              className="px-4 py-1.5 text-sm font-medium bg-purple-600 hover:bg-purple-700 text-white rounded transition flex items-center gap-2"
            >
              <Play className="w-4 h-4" />
              Publish & Execute
            </button>
          )}

          {contract.status === 'published' && (
            <>
              <button 
                onClick={() => handleStatusChange('paused')}
                className="px-3 py-1.5 text-sm font-medium border border-border rounded hover:bg-muted transition flex items-center gap-2 text-orange-400"
              >
                <Pause className="w-4 h-4" />
                Pause
              </button>
              <button 
                onClick={() => handleStatusChange('archived')}
                className="px-3 py-1.5 text-sm font-medium border border-border rounded hover:bg-muted transition flex items-center gap-2 text-neutral-400"
              >
                <Archive className="w-4 h-4" />
                Archive
              </button>
            </>
          )}
        </div>
      </header>

      {/* Main Workspace */}
      <div className="flex-1 overflow-hidden relative">
        <PanelGroup direction="horizontal">
          
          {/* Version History Sidebar */}
          {showHistory && (
            <>
              <Panel defaultSize={20} minSize={15} maxSize={30}>
                <VersionHistoryPanel />
              </Panel>
              <PanelResizeHandle className="w-1 bg-border hover:bg-blue-500 transition-colors cursor-col-resize" />
            </>
          )}

          <Panel defaultSize={showHistory ? 80 : 100}>
            <PanelGroup direction="vertical">
              <Panel defaultSize={75} minSize={30}>
                <PanelGroup direction="horizontal">
                  
                  {/* Left: Visual Builder */}
                  <Panel defaultSize={50} minSize={30} className="relative h-full border-r border-border">
                    {showTemplates ? (
                      <div className="p-6 h-full overflow-y-auto custom-scrollbar">
                        <TemplateMarketplace />
                      </div>
                    ) : (
                      <VisualBuilder />
                    )}
                  </Panel>
                  
                  <PanelResizeHandle className="w-1 bg-border hover:bg-blue-500 transition-colors cursor-col-resize" />
                  
                  {/* Right: Monaco Editor or Diff Viewer */}
                  <Panel defaultSize={50} minSize={30}>
                    {showDiffViewer ? (
                      <div className="h-full flex flex-col">
                        <div className="bg-[#1e1e1e] border-b border-[#333] px-4 py-2 flex justify-between items-center shrink-0">
                          <span className="text-sm font-mono text-muted-foreground">Comparing: <span className="text-blue-400 font-bold">Version {selectedVersionObj.version}</span> vs <span className="text-green-400 font-bold">Current</span></span>
                        </div>
                        <div className="flex-1">
                          <DiffViewer original={selectedVersionObj.yaml} modified={yaml} readOnly={true} />
                        </div>
                      </div>
                    ) : (
                      <YamlEditor value={yaml} onChange={(val) => setYaml(val || '')} />
                    )}
                  </Panel>
                </PanelGroup>
              </Panel>
              
              <PanelResizeHandle className="h-1 bg-border hover:bg-blue-500 transition-colors cursor-row-resize" />
              
              {/* Bottom: Live Preview */}
              <Panel defaultSize={25} minSize={15}>
                <LivePreviewPanel />
              </Panel>
            </PanelGroup>
          </Panel>
        </PanelGroup>
      </div>

      <ReviewDeployModal 
        isOpen={showReviewModal}
        onClose={() => setShowReviewModal(false)}
        onConfirm={executeDeploy}
      />
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { api } from "@/lib/apiClient";

export default function NewContract() {
  const router = useRouter();
  const [formData, setFormData] = useState({
    contract_name: "",
    owner: "",
    dataset: {
      source: "snowflake",
      database: "",
      schema: "",
      table: "",
    },
    rules: [{ type: "not_null", column: "" }]
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState("");

  const handleDatasetChange = (field: string, value: string) => {
    setFormData({
      ...formData,
      dataset: { ...formData.dataset, [field]: value }
    });
  };

  const addRule = () => {
    setFormData({
      ...formData,
      rules: [...formData.rules, { type: "not_null", column: "" }]
    });
  };

  const updateRule = (index: number, field: string, value: any) => {
    const newRules = [...formData.rules];
    newRules[index] = { ...newRules[index], [field]: value };
    setFormData({ ...formData, rules: newRules });
  };

  const handleTypeChange = (index: number, type: string) => {
    const newRules = [...formData.rules];
    let defaultRule: any = { type, column: "" };
    
    if (type === "freshness") {
      defaultRule = { type, freshness_minutes: 60 };
    } else if (type === "row_count_drop") {
      defaultRule = { type, threshold: "20%" };
    } else if (type === "numeric_range") {
      defaultRule = { type, column: "", min: 0, max: 100000 };
    }
    
    newRules[index] = defaultRule;
    setFormData({ ...formData, rules: newRules });
  };

  const removeRule = (index: number) => {
    const newRules = formData.rules.filter((_, i) => i !== index);
    setFormData({ ...formData, rules: newRules });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError("");

    try {
      const token = localStorage.getItem("token");
      if (!token) throw new Error("Not authenticated");

      const payload = {
        structured_data: formData
      };

      await api.post("/contracts", payload);

      router.push("/contracts");
    } catch (err: any) {
      setError(err.message || "Failed to create contract");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-extrabold text-foreground">New Contract</h2>
          <p className="text-muted-foreground">Define your data quality rules</p>
        </div>
        <Link href="/contracts" className="text-muted-foreground hover:text-foreground transition-colors">
          Cancel
        </Link>
      </div>

      {error && (
        <div className="bg-red-500/10 border border-red-500/50 text-red-500 p-4 rounded-lg">
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-8 glass-card p-8">
        {/* Metadata */}
        <div>
          <h3 className="text-xl font-bold mb-4 text-foreground border-b border-border pb-2">1. Metadata</h3>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-muted-foreground mb-1">Contract Name</label>
              <input 
                type="text" 
                required
                className="w-full bg-muted border border-border rounded-lg px-4 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.contract_name}
                onChange={(e) => setFormData({...formData, contract_name: e.target.value})}
                placeholder="e.g. analytics_orders_v1"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-muted-foreground mb-1">Owner Email / Team</label>
              <input 
                type="text" 
                required
                className="w-full bg-muted border border-border rounded-lg px-4 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.owner}
                onChange={(e) => setFormData({...formData, owner: e.target.value})}
                placeholder="e.g. data_eng@company.com"
              />
            </div>
          </div>
        </div>

        {/* Dataset */}
        <div>
          <h3 className="text-xl font-bold mb-4 text-foreground border-b border-border pb-2">2. Dataset Setup</h3>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-muted-foreground mb-1">Source</label>
              <select 
                className="w-full bg-muted border border-border rounded-lg px-4 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.dataset.source}
                onChange={(e) => handleDatasetChange("source", e.target.value)}
              >
                <option value="snowflake">Snowflake</option>
                <option value="delta">Delta Lake</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-muted-foreground mb-1">Database</label>
              <input 
                type="text" 
                required
                className="w-full bg-muted border border-border rounded-lg px-4 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.dataset.database}
                onChange={(e) => handleDatasetChange("database", e.target.value)}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-muted-foreground mb-1">Schema</label>
              <input 
                type="text" 
                required
                className="w-full bg-muted border border-border rounded-lg px-4 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.dataset.schema}
                onChange={(e) => handleDatasetChange("schema", e.target.value)}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-muted-foreground mb-1">Table</label>
              <input 
                type="text" 
                required
                className="w-full bg-muted border border-border rounded-lg px-4 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.dataset.table}
                onChange={(e) => handleDatasetChange("table", e.target.value)}
              />
            </div>
          </div>
        </div>

        {/* Rules */}
        <div>
          <div className="flex items-center justify-between mb-4 border-b border-border pb-2">
            <h3 className="text-xl font-bold text-foreground">3. Quality Rules</h3>
            <button 
              type="button" 
              onClick={addRule}
              className="text-sm bg-muted hover:bg-border border border-border text-foreground px-3 py-1 rounded-md transition"
            >
              + Add Rule
            </button>
          </div>
          
          <div className="space-y-4">
            {formData.rules.map((rule: any, index: number) => (
              <div key={index} className="flex flex-col gap-4 bg-card p-4 rounded-lg border border-border">
                <div className="flex items-start gap-4">
                  <div className="w-1/3">
                    <label className="block text-xs font-medium text-muted-foreground mb-1">Rule Type</label>
                    <select 
                      className="w-full bg-muted border border-border rounded-lg px-3 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none"
                      value={rule.type}
                      onChange={(e) => handleTypeChange(index, e.target.value)}
                    >
                      <option value="not_null">Not Null</option>
                      <option value="unique">Unique</option>
                      <option value="freshness">Freshness SLA</option>
                      <option value="row_count_drop">Row Count Drop</option>
                      <option value="numeric_range">Numeric Range</option>
                    </select>
                  </div>
                  
                  {/* Dynamic Fields */}
                  <div className="flex-1 grid grid-cols-2 gap-4">
                    {['not_null', 'unique', 'numeric_range'].includes(rule.type) && (
                      <div>
                        <label className="block text-xs font-medium text-muted-foreground mb-1">Column</label>
                        <input 
                          type="text" 
                          required
                          className="w-full bg-muted border border-border rounded-lg px-3 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none"
                          value={rule.column || ""}
                          onChange={(e) => updateRule(index, "column", e.target.value)}
                          placeholder="e.g. order_id"
                        />
                      </div>
                    )}
                    
                    {rule.type === 'freshness' && (
                      <div>
                        <label className="block text-xs font-medium text-muted-foreground mb-1">Max Delay (Minutes)</label>
                        <input 
                          type="number" 
                          required
                          className="w-full bg-muted border border-border rounded-lg px-3 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none"
                          value={rule.freshness_minutes || 60}
                          onChange={(e) => updateRule(index, "freshness_minutes", parseInt(e.target.value))}
                        />
                      </div>
                    )}

                    {rule.type === 'row_count_drop' && (
                      <div>
                        <label className="block text-xs font-medium text-muted-foreground mb-1">Drop Threshold (%)</label>
                        <input 
                          type="text" 
                          required
                          className="w-full bg-muted border border-border rounded-lg px-3 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none"
                          value={rule.threshold || "20%"}
                          onChange={(e) => updateRule(index, "threshold", e.target.value)}
                          placeholder="20%"
                        />
                      </div>
                    )}

                    {rule.type === 'numeric_range' && (
                      <>
                        <div>
                          <label className="block text-xs font-medium text-muted-foreground mb-1">Minimum</label>
                          <input 
                            type="number" 
                            required
                            className="w-full bg-muted border border-border rounded-lg px-3 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none"
                            value={rule.min !== undefined ? rule.min : 0}
                            onChange={(e) => updateRule(index, "min", parseInt(e.target.value))}
                          />
                        </div>
                        <div>
                          <label className="block text-xs font-medium text-muted-foreground mb-1">Maximum</label>
                          <input 
                            type="number" 
                            required
                            className="w-full bg-muted border border-border rounded-lg px-3 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none"
                            value={rule.max !== undefined ? rule.max : 100000}
                            onChange={(e) => updateRule(index, "max", parseInt(e.target.value))}
                          />
                        </div>
                      </>
                    )}
                  </div>

                  <div className="mt-5 ml-2">
                    <button 
                      type="button" 
                      onClick={() => removeRule(index)}
                      className="text-red-500 hover:text-red-400 text-sm font-medium transition"
                    >
                      Remove
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="pt-6 border-t border-border">
          <button 
            type="submit" 
            disabled={isSubmitting}
            className="w-full bg-gradient-to-r from-blue-500 to-purple-600 hover:from-blue-600 hover:to-purple-700 text-white font-bold py-3 rounded-lg transition shadow-lg disabled:opacity-50"
          >
            {isSubmitting ? "Deploying..." : "Deploy Contract"}
          </button>
        </div>
      </form>
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import Link from "next/link";
import { useContracts } from "@/queries/useContracts";
import { DataTable } from "@/components/ui/DataTable";
import { ColumnDef } from "@tanstack/react-table";
import { ArrowUpDown } from "lucide-react";

export default function ContractsPage() {
  const router = useRouter();
  const { data: contracts = [], isLoading, isError } = useContracts();

  if (isError) {
    if (typeof window !== "undefined" && !localStorage.getItem("token")) {
      router.push("/auth/login");
    }
  }

  const columns: ColumnDef<any>[] = [
    {
      accessorKey: "name",
      header: ({ column }) => {
        return (
          <button
            className="flex items-center hover:text-foreground transition-colors"
            onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
          >
            Name
            <ArrowUpDown className="ml-2 h-4 w-4" />
          </button>
        )
      },
      cell: ({ row }) => (
        <div className="font-medium text-foreground">
          {row.getValue("name")}
        </div>
      ),
    },
    {
      accessorKey: "dataset_source",
      header: "Source",
    },
    {
      accessorKey: "dataset_table",
      header: "Table",
    },
    {
      id: "versions",
      header: "Versions",
      cell: ({ row }) => {
        const versions = row.original.versions;
        return (
          <span className="px-2 py-1 bg-muted text-foreground rounded text-xs font-mono border border-border">
            v{versions?.length || 1}
          </span>
        )
      }
    },
    {
      id: "actions",
      header: "Actions",
      cell: ({ row }) => {
        return (
          <Link href={`/contracts/${row.original.id}`} className="text-blue-500 hover:text-blue-600 dark:text-blue-400 dark:hover:text-blue-300 transition-colors font-medium">
            View Details →
          </Link>
        )
      }
    }
  ];

  if (isLoading) {
    return <div className="flex justify-center py-20 text-foreground">Loading Contracts...</div>;
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-foreground mb-2">Contract Registry</h1>
          <p className="text-muted-foreground">Manage all data schemas and quality rules</p>
        </div>
        <Link href="/contracts/author" className="bg-gradient-to-r from-blue-500 to-purple-600 hover:from-blue-600 hover:to-purple-700 text-white font-bold py-2 px-4 rounded-lg transition shadow-lg inline-flex items-center gap-2">
          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14"/><path d="M12 5v14"/></svg>
          New Contract
        </Link>
      </div>

      <DataTable columns={columns} data={contracts} />
    </div>
  );
}

"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useQuery } from "@tanstack/react-query";
import { api } from "@/lib/apiClient";

export default function DbtCatalog() {
  const router = useRouter();

  const { data: models = [], isLoading: loadingModels, isError: isModelsError } = useQuery({
    queryKey: ["dbt_models"],
    queryFn: () => api.get<any[]>("/dbt/models"),
  });

  const { data: sources = [], isLoading: loadingSources, isError: isSourcesError } = useQuery({
    queryKey: ["dbt_sources"],
    queryFn: () => api.get<any[]>("/dbt/sources"),
  });

  if (isModelsError || isSourcesError) {
    if (typeof window !== "undefined" && !localStorage.getItem("token")) {
      router.push("/auth/login");
    }
  }

  const loading = loadingModels || loadingSources;
  
  const assets = [
    ...models.map((m: any) => ({ ...m, resource_type: "model" })),
    ...sources.map((s: any) => ({ ...s, resource_type: "source" }))
  ];

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-extrabold text-foreground flex items-center gap-3">
            <Link href="/dbt" className="text-muted-foreground hover:text-foreground transition">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
            </Link>
            Asset Catalog
          </h2>
          <p className="text-muted-foreground mt-1">Discovered models, sources, and snapshots from your dbt project.</p>
        </div>
      </div>

      <div className="glass-card border border-border rounded-xl overflow-hidden">
        {loading ? (
          <div className="p-8 text-center text-muted-foreground">Scanning dbt metadata...</div>
        ) : assets.length === 0 ? (
          <div className="p-8 text-center text-muted-foreground">
            No assets found. Go back and click &quot;Sync Mock dbt Project&quot;.
          </div>
        ) : (
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="border-b border-border bg-muted/50">
                <th className="p-4 text-xs font-semibold text-muted-foreground uppercase tracking-wider">Asset Name</th>
                <th className="p-4 text-xs font-semibold text-muted-foreground uppercase tracking-wider">Type</th>
                <th className="p-4 text-xs font-semibold text-muted-foreground uppercase tracking-wider">Owner</th>
                <th className="p-4 text-xs font-semibold text-muted-foreground uppercase tracking-wider">Health Score</th>
                <th className="p-4 text-xs font-semibold text-muted-foreground uppercase tracking-wider">Contract</th>
                <th className="p-4 text-xs font-semibold text-muted-foreground uppercase tracking-wider">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {assets.map((asset) => (
                <tr key={asset.id} className="hover:bg-muted/30 transition-colors group">
                  <td className="p-4">
                    <div className="font-medium text-foreground flex items-center gap-2">
                      {asset.name}
                      {asset.tests && asset.tests.length === 0 && !asset.has_contract && (
                        <span className="px-2 py-0.5 rounded text-[10px] font-bold bg-red-500/20 text-red-500 dark:text-red-400 border border-red-500/30">
                          HIGH RISK
                        </span>
                      )}
                    </div>
                    <div className="text-xs text-muted-foreground mt-1">{asset.database}.{asset.schema_name}</div>
                  </td>
                  <td className="p-4">
                    <span className="px-2.5 py-1 rounded-full text-xs font-medium bg-blue-500/10 text-blue-500 dark:text-blue-400 border border-blue-500/20">
                      {asset.resource_type}
                    </span>
                  </td>
                  <td className="p-4 text-sm text-muted-foreground">{asset.owner || "Data Team"}</td>
                  <td className="p-4">
                    <div className="flex items-center gap-2">
                      <div className="w-full bg-muted rounded-full h-2 max-w-[100px]">
                        <div 
                          className={`h-2 rounded-full ${asset.health_score > 80 ? 'bg-green-500' : asset.health_score > 50 ? 'bg-yellow-500' : 'bg-red-500'}`} 
                          style={{ width: `${asset.health_score || 100}%` }}
                        ></div>
                      </div>
                      <span className="text-xs text-muted-foreground">{asset.health_score || 100}/100</span>
                    </div>
                  </td>
                  <td className="p-4">
                    {asset.has_contract ? (
                       <span className="inline-flex items-center gap-1 text-xs text-emerald-500 dark:text-emerald-400 bg-emerald-500/10 px-2 py-1 rounded border border-emerald-500/20">
                         <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
