        <div className="flex space-x-3">
           <button className="border border-border hover:bg-secondary px-4 py-2 rounded-md text-sm font-semibold transition-colors">
            Connect Repository
          </button>
          <Link href="/pull-requests" className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-md text-sm font-semibold transition-colors shadow-sm">
            View Pull Requests
          </Link>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="p-6 rounded-xl border border-border bg-card shadow-sm">
          <div className="flex items-center space-x-3 mb-4">
            <div className="p-2 bg-blue-500/10 text-blue-500 rounded-lg"><Github size={20} /></div>
            <h3 className="font-semibold text-muted-foreground text-sm uppercase tracking-wider">Connected Repos</h3>
          </div>
          <span className="text-4xl font-bold text-foreground">{repos?.length || 0}</span>
        </div>

        <div className="p-6 rounded-xl border border-border bg-card shadow-sm">
          <div className="flex items-center space-x-3 mb-4">
            <div className="p-2 bg-green-500/10 text-green-500 rounded-lg"><GitPullRequest size={20} /></div>
            <h3 className="font-semibold text-muted-foreground text-sm uppercase tracking-wider">Open PRs</h3>
          </div>
          <span className="text-4xl font-bold text-foreground">{openPRs}</span>
        </div>

        <div className="p-6 rounded-xl border border-border bg-card shadow-sm">
          <div className="flex items-center space-x-3 mb-4">
            <div className="p-2 bg-orange-500/10 text-orange-500 rounded-lg"><ShieldAlert size={20} /></div>
            <h3 className="font-semibold text-muted-foreground text-sm uppercase tracking-wider">High Risk PRs</h3>
          </div>
          <span className="text-4xl font-bold text-foreground">{highRiskPRs}</span>
        </div>

        <div className="p-6 rounded-xl border border-border bg-card shadow-sm">
          <div className="flex items-center space-x-3 mb-4">
            <div className="p-2 bg-red-500/10 text-red-500 rounded-lg"><XOctagon size={20} /></div>
            <h3 className="font-semibold text-muted-foreground text-sm uppercase tracking-wider">Blocked Deployments</h3>
          </div>
          <span className="text-4xl font-bold text-foreground">{blockedDeployments}</span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mt-8">
        <div className="p-6 rounded-xl border border-border bg-card shadow-sm">
          <h2 className="text-xl font-bold mb-6">Recent PR Activity</h2>
          <div className="overflow-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-secondary text-muted-foreground">
                <tr>
                  <th className="px-4 py-3 rounded-tl-lg font-semibold">PR</th>
                  <th className="px-4 py-3 font-semibold">Author</th>
                  <th className="px-4 py-3 rounded-tr-lg font-semibold">Risk</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border">
                {prs?.slice(0, 5).map((pr: any) => (
                  <tr key={pr.id} className="hover:bg-secondary/30 transition-colors">
                    <td className="px-4 py-3"><Link href={`/pull-requests/${pr.id}`} className="font-bold text-blue-500 hover:underline">#{pr.pr_number}</Link></td>
                    <td className="px-4 py-3">{pr.author}</td>
                    <td className="px-4 py-3">
                      <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${
                        pr.risk_level === 'CRITICAL' ? 'bg-red-500/10 text-red-500' :
                        pr.risk_level === 'HIGH' ? 'bg-orange-500/10 text-orange-500' :
                        pr.risk_level === 'MEDIUM' ? 'bg-yellow-500/10 text-yellow-500' :
                        'bg-green-500/10 text-green-500'
                      }`}>
                        {pr.risk_level || "UNKNOWN"}
                      </span>
                    </td>
                  </tr>
                ))}
                {prs?.length === 0 && (
                  <tr><td colSpan={3} className="px-4 py-4 text-center text-muted-foreground">No recent PRs.</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

        <div className="p-6 rounded-xl border border-border bg-card shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-bold">Risk Trend Chart</h2>
            <span className="text-sm text-muted-foreground bg-secondary px-3 py-1 rounded-full">Current Snapshot</span>
          </div>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={riskTrendData} margin={{ top: 20, right: 30, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="var(--border-border)" />
                <XAxis dataKey="name" stroke="var(--color-muted-foreground)" />
                <YAxis stroke="var(--color-muted-foreground)" />
                <RechartsTooltip cursor={{fill: 'var(--bg-secondary)'}} contentStyle={{backgroundColor: 'var(--bg-card)', borderColor: 'var(--border-border)'}} />
                <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                  {riskTrendData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client"

import React, { useState } from 'react';
import Link from 'next/link';
import { useParams, useRouter } from 'next/navigation';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '@/lib/apiClient';
import { AlertCircle, BrainCircuit, CheckCircle, Database, GitBranch, ArrowLeft, TerminalSquare, AlertTriangle, FileText, Check } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

export default function IncidentWarRoom() {
  const params = useParams();
  const router = useRouter();
  const queryClient = useQueryClient();
  const incidentId = params.id as string;

  const [isInvestigating, setIsInvestigating] = useState(false);

  // Fetch Incident Details (Mocked for now, assuming GET /incidents/{id} exists, or just use the list endpoint and filter)
  const { data: incidentsData = [] } = useQuery({
    queryKey: ["incidents"],
    queryFn: () => api.get<any[]>("/incidents"),
  });
  const incident = incidentsData.find((i: any) => i.id.toString() === incidentId);

  // Fetch AI Investigation Data
  const { data: reasonData, refetch: refetchReason } = useQuery({
    queryKey: ["incidentReason", incidentId],
    queryFn: () => api.get<any>(`/incidents/${incidentId}/reason`),
  });

  const { data: evidenceData, refetch: refetchEvidence } = useQuery({
    queryKey: ["incidentEvidence", incidentId],
    queryFn: () => api.get<any[]>(`/incidents/${incidentId}/evidence`),
  });

  const investigateMutation = useMutation({
    mutationFn: () => api.post(`/incidents/${incidentId}/investigate`, {}),
    onSuccess: () => {
      refetchReason();
      refetchEvidence();
      setIsInvestigating(false);
    }
  });

  const acceptFixMutation = useMutation({
    mutationFn: () => api.post(`/incidents/${incidentId}/accept-fix`, {}),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["incidentReason", incidentId] });
      alert("Fix deployed successfully!");
    }
  });

  const handleInvestigate = () => {
    setIsInvestigating(true);
    investigateMutation.mutate();
  };

  if (!incident) {
    return <div className="p-8">Loading incident or not found...</div>;
  }

  const hasAIResult = !!reasonData;
  const fix = reasonData?.suggested_fix;
  const isFixAccepted = fix?.status === 'ACCEPTED';

  return (
    <div className="p-8 space-y-6 max-w-7xl mx-auto text-foreground animate-in fade-in duration-500 pb-20">
      
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <button onClick={() => router.push('/incidents')} className="p-2 hover:bg-secondary rounded-full transition-colors">
            <ArrowLeft size={20} />
          </button>
          <div className={`p-3 rounded-xl ${incident.status === 'OPEN' ? 'bg-red-500/10 text-red-500' : 'bg-gray-500/10 text-gray-500'}`}>
            <AlertCircle size={28} />
          </div>
          <div>
            <h1 className="text-3xl font-bold tracking-tight">INC-{incident.id}</h1>
            <p className="text-muted-foreground">{incident.severity} Validation Failure on {incident.asset_id}</p>
          </div>
        </div>
        <div>
          {!hasAIResult && (
             <button 
               onClick={handleInvestigate} 
               disabled={isInvestigating}
               className="bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2.5 rounded-lg text-sm font-semibold transition-all shadow-md flex items-center space-x-2 disabled:opacity-70 disabled:cursor-wait"
             >
               <BrainCircuit size={18} className={isInvestigating ? "animate-pulse" : ""} />
               <span>{isInvestigating ? "AI is investigating..." : "Investigate with AI"}</span>
             </button>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mt-8">
        {/* Left Column: Timeline & Evidence */}
        <div className="lg:col-span-2 space-y-6">
          
          {/* AI Reasoning / Timeline */}
          {hasAIResult && (
            <motion.div 
              initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}
              className="bg-card border border-border rounded-xl p-6 shadow-sm relative overflow-hidden"
            >
              <div className="absolute top-0 left-0 w-1 h-full bg-indigo-500"></div>
              <h2 className="text-lg font-bold flex items-center mb-4 text-indigo-500">
                <BrainCircuit size={20} className="mr-2" /> AI Root Cause Analysis
              </h2>
              
              <div className="bg-indigo-500/5 p-4 rounded-lg border border-indigo-500/20 mb-6">
