"use client"

import React from 'react';
import Link from 'next/link';
import { useQuery } from '@tanstack/react-query';
import { Users, Activity, ShieldAlert, ArrowRight } from 'lucide-react';

export default function TeamsPage() {
  const { data: teams, isLoading, error } = useQuery({
    queryKey: ['teams'],
    queryFn: async () => {
      const res = await fetch("/api/v1/teams");
      if (!res.ok) throw new Error("Failed to load teams");
      return res.json();
    }
  });

  if (isLoading) return <div className="p-8 text-muted-foreground animate-pulse">Loading Teams...</div>;
  if (error || !teams) return <div className="p-8 text-red-500">Failed to load teams.</div>;

  return (
    <div className="p-8 space-y-6 max-w-7xl mx-auto text-foreground">
      <div className="flex justify-between items-center mb-8">
        <div>
          <h1 className="text-3xl font-bold tracking-tight mb-2">Teams</h1>
          <p className="text-muted-foreground">Manage organizational groups, their owned assets, and performance metrics.</p>
        </div>
      </div>

      <div className="rounded-xl border border-border bg-card shadow-sm overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-secondary/50 text-muted-foreground text-sm uppercase">
            <tr>
              <th className="px-6 py-4 font-semibold">Team Name</th>
              <th className="px-6 py-4 font-semibold">Manager</th>
              <th className="px-6 py-4 font-semibold">Contact Email</th>
              <th className="px-6 py-4 font-semibold text-right">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-border">
            {teams.length === 0 ? (
              <tr><td colSpan={4} className="p-6 text-center text-muted-foreground">No teams found.</td></tr>
            ) : teams.map((team: any) => (
              <tr key={team.id} className="hover:bg-secondary/30 transition-colors">
                <td className="px-6 py-5">
                  <div className="flex items-center">
                    <div className="w-10 h-10 rounded-full bg-blue-500/10 text-blue-500 flex items-center justify-center mr-4">
                      <Users size={18} />
                    </div>
                    <span className="font-semibold">{team.team_name}</span>
                  </div>
                </td>
                <td className="px-6 py-5 text-muted-foreground">
                  {team.manager || 'Unassigned'}
                </td>
                <td className="px-6 py-5">
                  <span className="text-blue-500 hover:underline">{team.email || 'N/A'}</span>
                </td>
                <td className="px-6 py-5 text-right">
                  <Link href={`/teams/${team.id}`} className="inline-flex items-center text-sm font-medium text-blue-500 hover:text-blue-600">
                    View Details <ArrowRight size={16} className="ml-1" />
                  </Link>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Search, ChevronRight, ChevronDown, Database, LayoutGrid, Table, Loader2 } from "lucide-react";
import { useAIStudioStore } from "@/store/ai-studio-store";
import { api } from "@/lib/apiClient";

export default function AssetBrowser() {
  const [tree, setTree] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [expandedNodes, setExpandedNodes] = useState<Record<string, boolean>>({});
  
  const { selectedAssetId, setSelectedAssetId } = useAIStudioStore();

  useEffect(() => {
    async function fetchTree() {
      try {
        const data = await api.get<any>('/ai/contracts/assets');
        if (data.tree) {
          setTree(data.tree);
          // Auto-expand first node
          if (data.tree.length > 0) {
            setExpandedNodes({ [data.tree[0].id]: true });
          }
        }
      } catch (err) {
        console.error("Failed to load asset tree", err);
      } finally {
        setIsLoading(false);
      }
    }
    fetchTree();
  }, []);

  const toggleNode = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setExpandedNodes(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const getIcon = (type: string) => {
    switch (type) {
      case 'source': return <Database className="w-4 h-4 text-blue-500" />;
      case 'database': return <LayoutGrid className="w-4 h-4 text-purple-500" />;
      case 'table': return <Table className="w-4 h-4 text-emerald-500" />;
      default: return <Database className="w-4 h-4" />;
    }
  };

  const renderNode = (node: any, depth = 0) => {
    const isExpanded = expandedNodes[node.id];
    const isSelected = selectedAssetId === node.name; // Using name as ID for mock
    const hasChildren = node.children && node.children.length > 0;

    return (
      <div key={node.id}>
        <div 
          className={`flex items-center gap-2 py-1.5 px-2 cursor-pointer rounded-md transition-colors ${isSelected ? 'bg-primary/10 text-primary' : 'hover:bg-muted text-foreground'}`}
          style={{ paddingLeft: `${depth * 12 + 8}px` }}
          onClick={(e) => node.type === 'table' ? setSelectedAssetId(node.name) : toggleNode(node.id, e)}
        >
          <div className="w-4 flex items-center justify-center">
            {hasChildren && (
              <button onClick={(e) => toggleNode(node.id, e)} className="text-muted-foreground hover:text-foreground">
                {isExpanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
              </button>
            )}
          </div>
          {getIcon(node.type)}
          <span className="text-sm font-medium truncate">{node.name}</span>
        </div>
        
        {isExpanded && hasChildren && (
          <div>
            {node.children.map((child: any) => renderNode(child, depth + 1))}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full w-full">
      <div className="p-4 border-b border-border">
        <h3 className="font-semibold text-foreground mb-4">Asset Browser</h3>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <input 
            type="text" 
            placeholder="Search assets..." 
            className="w-full bg-background border border-border rounded-lg pl-9 pr-4 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-primary"
          />
        </div>
      </div>
      
      <div className="flex-1 overflow-y-auto p-2">
        {isLoading ? (
          <div className="flex justify-center p-8">
            <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
          </div>
        ) : (
          tree.map(node => renderNode(node))
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useAIStudioStore } from "@/store/ai-studio-store";
import { api } from "@/lib/apiClient";
import { Loader2, Database, ShieldCheck, Activity, Users, FileDigit } from "lucide-react";
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

export default function AssetOverview() {
  const { selectedAssetId } = useAIStudioStore();
  const [data, setData] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (!selectedAssetId) return;
    
    async function fetchDetails() {
      setIsLoading(true);
      try {
        const res = await api.get(`/ai/contracts/${selectedAssetId}`);
        setData(res);
      } catch (err) {
        console.error("Failed to load asset details", err);
      } finally {
        setIsLoading(false);
      }
    }
    fetchDetails();
  }, [selectedAssetId]);

  if (isLoading) {
    return (
      <div className="bg-card border border-border rounded-xl p-8 flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-ai" />
      </div>
    );
  }

  if (!data) return null;

  return (
    <div className="bg-card border border-border rounded-xl shadow-sm overflow-hidden flex flex-col">
      {/* Header Info */}
      <div className="p-6 border-b border-border flex items-start justify-between">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <span className="px-2 py-0.5 rounded-full bg-ai/10 text-ai text-xs font-semibold tracking-wide uppercase">Table</span>
