                <span className="text-xs text-muted-foreground font-mono">{col.type}</span>
              </div>
            ))}
            {data.schema.length > 4 && (
              <div className="text-xs text-center text-muted-foreground pt-2">+{data.schema.length - 4} more columns</div>
            )}
          </div>
        </div>

        {/* Chart */}
        <div className="p-6 flex flex-col">
          <h3 className="text-sm font-semibold text-foreground mb-2">Historical Volume Trend</h3>
          <div className="flex-1 min-h-[120px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={data.profile.historical_trends} margin={{ top: 5, right: 0, left: -20, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorVolume" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#8b5cf6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="hsl(var(--border))" />
                <XAxis dataKey="date" hide />
                <YAxis tick={{ fontSize: 10, fill: 'hsl(var(--muted-foreground))' }} axisLine={false} tickLine={false} />
                <Tooltip 
                  contentStyle={{ backgroundColor: 'hsl(var(--card))', borderColor: 'hsl(var(--border))', borderRadius: '8px' }}
                  itemStyle={{ color: 'hsl(var(--foreground))' }}
                />
                <Area type="monotone" dataKey="volume" stroke="#8b5cf6" strokeWidth={2} fillOpacity={1} fill="url(#colorVolume)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useAIStudioStore } from "@/store/ai-studio-store";
import { api } from "@/lib/apiClient";
import { Loader2, Sparkles, CheckCircle2, Play, Check, X, Edit, MessageSquareText } from "lucide-react";

export default function RecommendationEngine() {
  const { selectedAssetId, isGenerating, setIsGenerating, setActiveDrawer, setCurrentYaml } = useAIStudioStore();
  const [recommendations, setRecommendations] = useState<any[]>([]);
  const [hasGenerated, setHasGenerated] = useState(false);

  const handleGenerate = async () => {
    setIsGenerating(true);
    try {
      // For the sake of UI we use a mock payload, but in a real scenario we'd call the /generate API
      await new Promise(r => setTimeout(r, 2000));
      const mockRules = [
        {
          id: 'rule-1',
          column: 'order_id',
          type: 'NOT NULL',
          confidence: 99,
          reason: 'Detected stable historical behavior',
          evidence: '0 nulls across 120 million rows during 90 days',
          sql_preview: 'SELECT count(*) FROM orders WHERE order_id IS NULL'
        },
        {
          id: 'rule-2',
          column: 'status',
          type: 'ACCEPTED VALUES',
          confidence: 97,
          reason: 'Categorical distribution is very tight',
          evidence: 'Only 4 distinct values observed: PENDING, SHIPPED, DELIVERED, CANCELLED',
          sql_preview: "SELECT status FROM orders WHERE status NOT IN ('PENDING', 'SHIPPED', 'DELIVERED', 'CANCELLED')"
        },
        {
          id: 'rule-3',
          column: 'amount',
          type: 'NUMERIC RANGE',
          confidence: 85,
          reason: 'Values rarely exceed typical purchase limits',
          evidence: '99.9% of transactions are between $0 and $5000',
          sql_preview: 'SELECT amount FROM orders WHERE amount < 0 OR amount > 5000'
        }
      ];
      setRecommendations(mockRules);
      setHasGenerated(true);
      
      // Update YAML editor with the generated rules
      const yamlStr = `version: 1\ncontract_name: ${selectedAssetId}_contract\ndataset: ${selectedAssetId}\nrules:\n  - type: not_null\n    column: order_id\n  - type: accepted_values\n    column: status\n    values: [PENDING, SHIPPED, DELIVERED, CANCELLED]\n  - type: numeric_range\n    column: amount\n    min: 0\n    max: 5000`;
      setCurrentYaml(yamlStr);
      
    } catch (err) {
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  if (!hasGenerated && !isGenerating) {
    return (
      <div className="bg-card border border-border rounded-xl shadow-sm flex flex-col items-center justify-center p-8 text-center h-full">
        <div className="w-16 h-16 rounded-full bg-ai/10 flex items-center justify-center mb-6">
          <Sparkles className="w-8 h-8 text-ai" />
        </div>
        <h3 className="text-xl font-bold mb-2">AI Contract Generator</h3>
        <p className="text-muted-foreground max-w-sm mb-6">
          Let our AI analyze historical patterns, profiling stats, and schema metadata to automatically suggest data contracts.
        </p>
        <button 
          onClick={handleGenerate}
          className="bg-ai hover:bg-ai-dark text-white px-6 py-3 rounded-lg font-medium flex items-center gap-2 transition-all shadow-lg shadow-ai/20 hover:shadow-ai/40"
        >
          <Sparkles className="w-4 h-4" /> Generate Contract
        </button>
      </div>
    );
  }

  if (isGenerating) {
    return (
      <div className="bg-card border border-border rounded-xl shadow-sm flex flex-col items-center justify-center p-8 text-center h-full">
        <Loader2 className="w-12 h-12 animate-spin text-ai mb-6" />
        <h3 className="text-xl font-bold mb-2">Analyzing Dataset...</h3>
        <div className="space-y-2 text-sm text-muted-foreground">
          <p className="flex items-center gap-2 justify-center"><CheckCircle2 className="w-4 h-4 text-emerald-500" /> Profiling 120M rows...</p>
          <p className="flex items-center gap-2 justify-center"><CheckCircle2 className="w-4 h-4 text-emerald-500" /> Scanning schema metadata...</p>
          <p className="flex items-center gap-2 justify-center animate-pulse"><Play className="w-3 h-3 text-ai" /> Detecting behavioral patterns...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-card border border-border rounded-xl shadow-sm flex flex-col h-full overflow-hidden">
      <div className="p-4 border-b border-border flex items-center justify-between bg-muted/30">
        <div className="flex items-center gap-2">
          <Sparkles className="w-5 h-5 text-ai" />
          <h3 className="font-semibold text-foreground">AI Recommendations</h3>
        </div>
        <span className="text-xs font-medium px-2 py-1 bg-emerald-500/10 text-emerald-600 rounded-md">
          {recommendations.length} Rules Generated
        </span>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {recommendations.map(rule => (
          <div key={rule.id} className="border border-border rounded-lg p-4 bg-background hover:border-primary/30 transition-all group">
            <div className="flex items-start justify-between mb-3">
              <div>
                <div className="flex items-center gap-2 mb-1">
                  <span className="font-mono text-sm font-bold">{rule.column}</span>
                  <span className="text-xs px-1.5 py-0.5 bg-secondary rounded text-muted-foreground">{rule.type}</span>
                </div>
                <p className="text-sm text-foreground">{rule.reason}</p>
              </div>
              <div className="flex flex-col items-end">
                <span className="text-xs text-muted-foreground mb-1">Confidence</span>
                <span className={`text-sm font-bold ${rule.confidence > 95 ? 'text-emerald-500' : rule.confidence > 80 ? 'text-amber-500' : 'text-red-500'}`}>
                  {rule.confidence}%
                </span>
              </div>
            </div>

            <div className="flex items-center gap-2 mt-4 pt-3 border-t border-border/50">
              <button 
                onClick={() => setActiveDrawer('explainability')}
                className="text-xs flex items-center gap-1 text-muted-foreground hover:text-ai transition-colors mr-auto"
              >
                <MessageSquareText className="w-3.5 h-3.5" /> Why?
              </button>
              
              <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                <button className="p-1.5 rounded-md hover:bg-emerald-500/10 hover:text-emerald-500 text-muted-foreground" title="Accept">
                  <Check className="w-4 h-4" />
                </button>
                <button className="p-1.5 rounded-md hover:bg-red-500/10 hover:text-red-500 text-muted-foreground" title="Reject">
                  <X className="w-4 h-4" />
                </button>
                <button className="p-1.5 rounded-md hover:bg-secondary text-muted-foreground" title="Edit">
                  <Edit className="w-4 h-4" />
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import React, { useRef } from 'react';
import { DiffEditor, useMonaco, Monaco } from '@monaco-editor/react';
import { configureMonacoYaml } from 'monaco-yaml';
import { contractJsonSchema } from '@/schemas/monacoYamlSchema';

interface DiffViewerProps {
  original: string;
  modified: string;
  readOnly?: boolean;
}

export function DiffViewer({ original, modified, readOnly = true }: DiffViewerProps) {
  const isConfigured = useRef(false);

  const handleBeforeMount = (monacoInstance: Monaco) => {
    if (!isConfigured.current) {
      configureMonacoYaml(monacoInstance, {
        enableSchemaRequest: true,
        schemas: [
          {
            uri: contractJsonSchema.uri,
            fileMatch: ['*'],
            schema: contractJsonSchema.schema,
          },
        ],
      });
      isConfigured.current = true;
    }
  };

  return (
    <div className="w-full h-full border border-border bg-[#1e1e1e] rounded-lg overflow-hidden">
      <DiffEditor
        height="100%"
        language="yaml"
        theme="vs-dark"
        original={original}
        modified={modified}
        beforeMount={handleBeforeMount}
        options={{
          minimap: { enabled: true },
          readOnly: readOnly,
          wordWrap: 'on',
          scrollBeyondLastLine: false,
          smoothScrolling: true,
          padding: { top: 16 },
          fontFamily: 'JetBrains Mono, Menlo, Monaco, Consolas, monospace',
          fontSize: 14,
          renderSideBySide: true,
        }}
      />
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { useContractStore } from '@/store/useContractStore';
import { DiffViewer } from '@/components/contracts/DiffViewer';
import { api } from '@/lib/apiClient';

interface ReviewDeployModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
}

export function ReviewDeployModal({ isOpen, onClose, onConfirm }: ReviewDeployModalProps) {
  const { contract, yaml } = useContractStore();
  const [activeTab, setActiveTab] = useState<'diff' | 'ai_review' | 'simulation'>('diff');
  const [isDeploying, setIsDeploying] = useState(false);
  const [aiFeedback, setAiFeedback] = useState<any>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  if (!isOpen) return null;

  const runAiReview = async () => {
    setLoadingAi(true);
    try {
      // Mock AI review, assuming backend endpoint isn't fully ready yet for AI review,
      // or we can call the real endpoint if it exists.
      setTimeout(() => {
        setAiFeedback({
          confidence: 94,
          findings: [
            { type: 'warning', text: 'Missing uniqueness check on primary key.' },
            { type: 'success', text: 'Excellent freshness threshold (15m).' }
          ]
        });
        setLoadingAi(false);
      }, 1500);
    } catch (e) {
      setLoadingAi(false);
    }
  };

  const handleDeploy = async () => {
    setIsDeploying(true);
    await onConfirm();
    setIsDeploying(false);
  };

  // Mock old published YAML for diff comparison
  const oldYaml = `contract_name: ${contract.contract_name || 'old_contract'}
owner: old_owner@company.com
status: published
dataset:
  source: snowflake
  database: raw
  schema: public
  table: old_table
rules: []
`;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-card w-11/12 max-w-5xl h-[85vh] rounded-xl border border-border flex flex-col shadow-2xl overflow-hidden">
        
        {/* Header */}
        <div className="px-6 py-4 border-b border-border flex items-center justify-between bg-muted/20">
          <div>
            <h2 className="text-xl font-bold text-foreground">Review Changes</h2>
            <p className="text-sm text-muted-foreground mt-1">Review your contract modifications before publishing to production.</p>
          </div>
          <button onClick={onClose} className="text-muted-foreground hover:text-foreground">
            ✕
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-border px-6 gap-6 bg-muted/10">
          <button 
            className={`py-3 text-sm font-medium border-b-2 transition-colors ${activeTab === 'diff' ? 'border-blue-500 text-blue-500' : 'border-transparent text-muted-foreground hover:text-foreground'}`}
            onClick={() => setActiveTab('diff')}
          >
            Visual Diff
          </button>
          <button 
            className={`py-3 text-sm font-medium border-b-2 transition-colors ${activeTab === 'simulation' ? 'border-blue-500 text-blue-500' : 'border-transparent text-muted-foreground hover:text-foreground'}`}
            onClick={() => setActiveTab('simulation')}
          >
            Simulation Results
          </button>
          <button 
            className={`py-3 text-sm font-medium border-b-2 transition-colors ${activeTab === 'ai_review' ? 'border-blue-500 text-blue-500' : 'border-transparent text-muted-foreground hover:text-foreground'}`}
            onClick={() => setActiveTab('ai_review')}
          >
            AI Code Review
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-hidden p-6 bg-[#121212]">
          {activeTab === 'diff' && (
            <div className="h-full rounded-lg overflow-hidden border border-border">
              <DiffViewer original={oldYaml} modified={yaml} />
            </div>
          )}

          {activeTab === 'simulation' && (
            <div className="h-full overflow-y-auto">
              <div className="grid grid-cols-3 gap-6">
                <div className="bg-card border border-border p-5 rounded-xl">
                  <p className="text-sm text-muted-foreground font-medium mb-1">Expected Success Rate</p>
                  <p className="text-3xl font-bold text-green-400">98.2%</p>
                  <p className="text-xs text-muted-foreground mt-2">Based on last 30 days of data.</p>
                </div>
                <div className="bg-card border border-border p-5 rounded-xl">
                  <p className="text-sm text-muted-foreground font-medium mb-1">False Positive Risk</p>
                  <p className="text-3xl font-bold text-yellow-400">3.1%</p>
                  <p className="text-xs text-muted-foreground mt-2">Mostly from freshness checks.</p>
                </div>
                <div className="bg-card border border-border p-5 rounded-xl">
                  <p className="text-sm text-muted-foreground font-medium mb-1">Estimated Cost / Run</p>
                  <p className="text-3xl font-bold text-foreground">$0.03</p>
                  <p className="text-xs text-muted-foreground mt-2">Will scan approx 2.4M rows.</p>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'ai_review' && (
            <div className="h-full flex flex-col items-center justify-center">
              {!aiFeedback && !loadingAi && (
                <button 
                  onClick={runAiReview}
                  className="bg-purple-600 hover:bg-purple-700 text-white font-bold py-3 px-6 rounded-lg transition shadow-lg flex items-center gap-2"
                >
                  ✨ Run AI Contract Review
                </button>
              )}
              {loadingAi && <div className="text-muted-foreground animate-pulse font-medium text-lg">AI is analyzing rules against historical telemetry...</div>}
              {aiFeedback && (
                <div className="w-full max-w-2xl bg-card border border-border rounded-xl p-6">
                  <div className="flex items-center justify-between mb-6">
                    <h3 className="text-xl font-bold text-foreground flex items-center gap-2">
                      ✨ AI Review Complete
                    </h3>
                    <div className="px-3 py-1 bg-green-500/10 text-green-400 font-bold rounded text-sm border border-green-500/20">
                      {aiFeedback.confidence}% Confidence
                    </div>
                  </div>
                  <div className="space-y-3">
                    {aiFeedback.findings.map((f: any, i: number) => (
                      <div key={i} className={`p-3 rounded border flex items-start gap-3 ${f.type === 'warning' ? 'bg-yellow-500/10 border-yellow-500/20 text-yellow-200' : 'bg-green-500/10 border-green-500/20 text-green-200'}`}>
                        <span>{f.type === 'warning' ? '⚠️' : '✅'}</span>
                        <p className="text-sm">{f.text}</p>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-border flex items-center justify-end gap-3 bg-muted/20">
          <button 
            onClick={onClose}
            className="px-4 py-2 text-sm font-medium border border-border rounded hover:bg-muted transition text-foreground"
          >
            Cancel
          </button>
          <button 
            onClick={handleDeploy}
            disabled={isDeploying}
            className="px-6 py-2 text-sm font-bold bg-blue-600 hover:bg-blue-700 text-white rounded transition disabled:opacity-50"
          >
            {isDeploying ? 'Deploying...' : 'Confirm & Publish'}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

