"use client";

import React, { useEffect } from 'react';
import { useForm, useFieldArray, Controller } from 'react-hook-form';
import { useContractStore, Rule } from '@/store/useContractStore';

// We don't strictly use zodResolver here for the sake of dynamic syncing without getting blocked by intermediate states,
// but we still provide a structured UI. The YAML parser handles true validation.

export function VisualBuilder() {
  const { contract, setContract } = useContractStore();

  const { register, control, watch, setValue, getValues } = useForm({
    defaultValues: {
      contract_name: contract.contract_name || '',
      owner: contract.owner || '',
      dataset: contract.dataset || { source: 'snowflake', database: '', schema: '', table: '' },
      rules: (contract.rules || []) as any[]
    },
    mode: 'onChange',
  });

  const { fields: ruleFields, append: addRule, remove: removeRule } = useFieldArray({
    control,
    name: 'rules',
  });

  const formValues = watch();

  useEffect(() => {
    // Only update Zustand if form actually changed relative to it
    // Deep equality check is simplified here for performance
    const stringifiedContract = JSON.stringify(contract);
    const stringifiedForm = JSON.stringify(formValues);
    
    if (stringifiedContract !== stringifiedForm) {
      setContract(() => formValues as any);
    }
  }, [formValues, contract, setContract]);

  // Sync external changes (from Monaco YAML) back to form
  useEffect(() => {
    const stringifiedContract = JSON.stringify(contract);
    const stringifiedForm = JSON.stringify(getValues());
    
    if (stringifiedContract !== stringifiedForm) {
      setValue('contract_name', contract.contract_name || '');
      setValue('owner', contract.owner || '');
      setValue('dataset', contract.dataset || { source: 'snowflake', database: '', schema: '', table: '' });
      setValue('rules', (contract.rules || []) as any[]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [contract, setValue]);

  const renderRuleInputs = (index: number, ruleType: string) => {
    switch(ruleType) {
      case 'not_null':
      case 'unique':
        return (
          <>
            <span className="text-muted-foreground text-sm font-medium">IS {ruleType === 'not_null' ? 'NOT NULL' : 'UNIQUE'}</span>
          </>
        );
      case 'accepted_values':
        return (
          <>
            <span className="text-muted-foreground text-sm font-medium">IN</span>
            <input 
              type="text" 
              {...register(`rules.${index}.values`)}
              className="bg-muted border border-border rounded-lg px-3 py-1.5 text-foreground focus:ring-2 focus:ring-blue-500 outline-none text-sm placeholder:text-muted-foreground/50 w-48"
              placeholder="e.g. 'A', 'B', 'C'"
            />
          </>
        );
      case 'numeric_range':
        return (
          <>
            <span className="text-muted-foreground text-sm font-medium">BETWEEN</span>
            <input 
              type="number" 
              {...register(`rules.${index}.min`)}
              className="bg-muted border border-border rounded-lg px-3 py-1.5 text-foreground focus:ring-2 focus:ring-blue-500 outline-none text-sm w-24"
              placeholder="Min"
            />
            <span className="text-muted-foreground text-sm font-medium">AND</span>
            <input 
              type="number" 
              {...register(`rules.${index}.max`)}
              className="bg-muted border border-border rounded-lg px-3 py-1.5 text-foreground focus:ring-2 focus:ring-blue-500 outline-none text-sm w-24"
              placeholder="Max"
            />
          </>
        );
      case 'freshness':
        return (
          <>
            <span className="text-muted-foreground text-sm font-medium">DELAY {'<'}</span>
            <div className="flex items-center gap-2">
              <input 
                type="number" 
                {...register(`rules.${index}.freshness_minutes`)}
                className="bg-muted border border-border rounded-lg px-3 py-1.5 text-foreground focus:ring-2 focus:ring-blue-500 outline-none text-sm w-24"
                placeholder="60"
              />
              <span className="text-muted-foreground text-sm">minutes</span>
            </div>
          </>
        );
      case 'row_count_drop':
        return (
          <>
            <span className="text-muted-foreground text-sm font-medium">DROP EXCEEDS</span>
            <div className="flex items-center gap-2">
              <input 
                type="text" 
                {...register(`rules.${index}.threshold`)}
                className="bg-muted border border-border rounded-lg px-3 py-1.5 text-foreground focus:ring-2 focus:ring-blue-500 outline-none text-sm w-24"
                placeholder="20"
              />
              <span className="text-muted-foreground text-sm">%</span>
            </div>
          </>
        );
      case 'custom_sql':
        return (
          <>
            <span className="text-muted-foreground text-sm font-medium">PASSES SQL</span>
            <textarea 
              {...register(`rules.${index}.sql`)}
              className="bg-[#1e1e1e] border border-border rounded-lg px-3 py-1.5 text-green-400 font-mono text-sm focus:ring-2 focus:ring-blue-500 outline-none w-full max-w-md h-12"
              placeholder="SELECT COUNT(*) FROM {{table}} WHERE ..."
            />
          </>
        );
      default:
        return null;
    }
  };

  return (
    <div className="h-full overflow-y-auto p-6 space-y-8 bg-background custom-scrollbar pb-32">
      {/* 1. Metadata Form */}
      <div>
        <h3 className="text-lg font-bold mb-4 text-foreground border-b border-border pb-2">1. Metadata</h3>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-xs font-semibold text-muted-foreground mb-1 uppercase tracking-wider">Contract Name</label>
            <input 
              type="text" 
              {...register("contract_name")}
              className="w-full bg-muted border border-border rounded-lg px-4 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none transition"
              placeholder="e.g. analytics_orders_v1"
            />
          </div>
          <div>
            <label className="block text-xs font-semibold text-muted-foreground mb-1 uppercase tracking-wider">Owner Email</label>
            <input 
              type="email" 
              {...register("owner")}
              className="w-full bg-muted border border-border rounded-lg px-4 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none transition"
              placeholder="e.g. data_eng@company.com"
            />
          </div>
        </div>
      </div>

      {/* 2. Dataset Setup */}
      <div>
        <h3 className="text-lg font-bold mb-4 text-foreground border-b border-border pb-2">2. Dataset Details</h3>
        <div className="grid grid-cols-4 gap-4">
          <div>
            <label className="block text-xs font-semibold text-muted-foreground mb-1 uppercase tracking-wider">Source</label>
            <select 
              {...register("dataset.source")}
              className="w-full bg-muted border border-border rounded-lg px-3 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none text-sm"
            >
              <option value="snowflake">Snowflake</option>
              <option value="delta">Delta Lake</option>
              <option value="bigquery">BigQuery</option>
              <option value="redshift">Redshift</option>
              <option value="postgres">PostgreSQL</option>
            </select>
          </div>
          <div>
            <label className="block text-xs font-semibold text-muted-foreground mb-1 uppercase tracking-wider">Database</label>
            <input 
              type="text" 
              {...register("dataset.database")}
              className="w-full bg-muted border border-border rounded-lg px-3 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none transition text-sm"
            />
          </div>
          <div>
            <label className="block text-xs font-semibold text-muted-foreground mb-1 uppercase tracking-wider">Schema</label>
            <input 
              type="text" 
              {...register("dataset.schema")}
              className="w-full bg-muted border border-border rounded-lg px-3 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none transition text-sm"
            />
          </div>
          <div>
            <label className="block text-xs font-semibold text-muted-foreground mb-1 uppercase tracking-wider">Table</label>
            <input 
              type="text" 
              {...register("dataset.table")}
              className="w-full bg-muted border border-border rounded-lg px-3 py-2 text-foreground focus:ring-2 focus:ring-blue-500 outline-none transition text-sm"
            />
          </div>
        </div>
      </div>

      {/* 3. Visual Rule Builder */}
      <div>
        <div className="flex items-center justify-between mb-4 border-b border-border pb-2">
          <h3 className="text-lg font-bold text-foreground">3. Quality Rules</h3>
          <button 
            type="button" 
            onClick={() => addRule({ type: 'not_null', severity: 'error' })}
            className="text-xs bg-blue-500/10 hover:bg-blue-500/20 text-blue-500 font-semibold px-3 py-1.5 rounded-md transition border border-blue-500/30"
          >
            + Add Rule
          </button>
        </div>
        
        <div className="space-y-3">
          {ruleFields.map((field, index) => {
            const ruleType = watch(`rules.${index}.type`);
            const ruleSeverity = watch(`rules.${index}.severity`) || 'error';
            
            const severityColor = {
              info: 'border-blue-500/30 bg-blue-500/5',
              warning: 'border-yellow-500/30 bg-yellow-500/5',
              error: 'border-red-500/30 bg-red-500/5',
              critical: 'border-purple-500/30 bg-purple-500/5',
            }[ruleSeverity as string] || 'border-border bg-card';

            return (
              <div key={field.id} className={`flex flex-col gap-3 p-4 rounded-xl border shadow-sm relative group transition-colors ${severityColor}`}>
                
                {/* Delete Button */}
                <button 
                  type="button"
                  onClick={() => removeRule(index)}
                  className="absolute top-3 right-3 text-muted-foreground hover:text-red-500 transition opacity-0 group-hover:opacity-100"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18"></path><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"></path><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"></path></svg>
                </button>

                {/* Grafana-style Sentence Builder */}
                <div className="flex flex-wrap items-center gap-3 w-full pr-8">
                  <span className="text-muted-foreground text-sm font-bold uppercase tracking-wide">IF</span>
                  
                  {/* Target (Column or Table level) */}
                  {ruleType !== 'row_count_drop' && ruleType !== 'custom_sql' ? (
                    <input 
                      type="text" 
                      {...register(`rules.${index}.column`)}
                      className="bg-muted border border-border rounded-lg px-3 py-1.5 text-foreground focus:ring-2 focus:ring-blue-500 outline-none text-sm font-mono w-48 placeholder:font-sans placeholder:text-muted-foreground/50"
                      placeholder="column_name"
                    />
                  ) : (
                    <span className="bg-muted border border-border rounded-lg px-3 py-1.5 text-foreground text-sm font-mono opacity-80 cursor-not-allowed">
                      Dataset (Table)
                    </span>
                  )}
                  
                  {/* Operator / Rule Type */}
                  <select 
                    {...register(`rules.${index}.type`)}
                    className="bg-muted border border-border rounded-lg px-3 py-1.5 text-foreground focus:ring-2 focus:ring-blue-500 outline-none text-sm font-medium"
                  >
                    <option value="not_null">Not Null</option>
                    <option value="unique">Unique</option>
                    <option value="accepted_values">Accepted Values</option>
                    <option value="freshness">Freshness</option>
                    <option value="row_count_drop">Row Count Drop</option>
                    <option value="numeric_range">Numeric Range</option>
                    <option value="custom_sql">Custom SQL</option>
                  </select>

                  {/* Dynamic Inputs */}
                  {renderRuleInputs(index, ruleType)}

                  <span className="text-muted-foreground text-sm font-bold uppercase tracking-wide ml-2">THEN</span>

                  {/* Severity */}
                  <select 
                    {...register(`rules.${index}.severity`)}
                    className={`border rounded-lg px-3 py-1.5 outline-none text-sm font-bold transition-colors focus:ring-2 focus:ring-blue-500 ${
                      ruleSeverity === 'info' ? 'bg-blue-500/10 text-blue-500 border-blue-500/30' :
                      ruleSeverity === 'warning' ? 'bg-yellow-500/10 text-yellow-500 border-yellow-500/30' :
                      ruleSeverity === 'critical' ? 'bg-purple-500/10 text-purple-500 border-purple-500/30' :
                      'bg-red-500/10 text-red-500 border-red-500/30'
                    }`}
                  >
                    <option value="info">INFO</option>
                    <option value="warning">WARNING</option>
                    <option value="error">ERROR</option>
                    <option value="critical">CRITICAL</option>
                  </select>
                </div>
                
                {/* Optional Description */}
                <div className="w-full mt-1">
                  <input
                    type="text"
                    {...register(`rules.${index}.description`)}
                    className="w-full bg-transparent border-none text-xs text-muted-foreground outline-none placeholder:text-muted-foreground/30 px-1"
                    placeholder="Add an optional description or runbook link for this rule..."
                  />
                </div>
              </div>
            );
          })}
          
          {ruleFields.length === 0 && (
            <div className="text-center py-10 border-2 border-dashed border-border rounded-xl bg-muted/20">
              <p className="text-muted-foreground text-sm mb-3">No rules defined for this contract yet.</p>
              <button 
                type="button"
                onClick={() => addRule({ type: 'not_null', severity: 'error' })}
                className="bg-primary text-primary-foreground px-4 py-2 rounded-lg text-sm font-medium hover:bg-primary/90 transition shadow-sm"
              >
                Create Your First Rule
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { usePathname } from 'next/navigation';
import { 
  Bot, X, Maximize2, Minimize2, Send, Database, Shield, AlertTriangle, Users, BookOpen, Sparkles 
} from 'lucide-react';
import ReactMarkdown from 'react-markdown';

interface Message {
  id: number;
  role: "user" | "assistant";
  content: string;
  context?: { asset: string; type: string };
  actions?: string[];
}

// Mock Conversation History
const initialMessages: Message[] = [
  {
    id: 1,
    role: "assistant",
    content: "Hi! I'm DataPact AI. I noticed you are viewing the **fct_sales** dataset. The null rate for `customer_id` has spiked to 2.4% today.\n\nWould you like me to run an investigation?",
    context: { asset: "analytics.fct_sales", type: "anomaly" }
  }
];

export default function PersistentCopilot({ overrideVisibility = false }: { overrideVisibility?: boolean }) {
  const [isOpen, setIsOpen] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [messages, setMessages] = useState(initialMessages);
  const [input, setInput] = useState("");
  const pathname = usePathname();
  
  // If overridden by RightSidebar, it's always "open" and not floating
  const isEffectivelyOpen = overrideVisibility || isOpen;

  // Determine current context based on route
  const getContext = () => {
    if (pathname?.includes('/assets')) return { icon: <Database className="w-4 h-4"/>, label: "Asset Catalog" };
    if (pathname?.includes('/contracts')) return { icon: <Shield className="w-4 h-4"/>, label: "Data Contracts" };
    if (pathname?.includes('/incidents')) return { icon: <AlertTriangle className="w-4 h-4"/>, label: "Incidents" };
    if (pathname?.includes('/ownership')) return { icon: <Users className="w-4 h-4"/>, label: "Ownership" };
    return { icon: <Bot className="w-4 h-4"/>, label: "Workspace" };
  };

  const currentContext = getContext();

  const handleSend = () => {
    if (!input.trim()) return;
    
    // Add user message
    const newMsg: Message = { id: Date.now(), role: "user", content: input };
    setMessages(prev => [...prev, newMsg]);
    setInput("");

    // Mock AI response
    setTimeout(() => {
      setMessages(prev => [
        ...prev, 
        { 
          id: Date.now(), 
          role: "assistant", 
          content: "I've analyzed the lineage for this dataset. The issue seems to originate from `stg_payments`. \n\n**Confidence: 94%**\n\nI recommend restarting the upstream Airflow DAG.",
          actions: ["Restart DAG", "View Lineage"]
        } as Message
      ]);
    }, 1000);
  };

  if (!isEffectivelyOpen) {
    return (
      <button 
        onClick={() => setIsOpen(true)}
        className="fixed bottom-6 right-6 bg-gradient-to-r from-blue-600 to-purple-600 text-white p-4 rounded-full shadow-lg shadow-purple-500/20 hover:scale-105 transition-transform z-50 flex items-center justify-center"
      >
        <Sparkles className="w-6 h-6" />
      </button>
    );
  }

  return (
    <div className={overrideVisibility ? "h-full w-full flex flex-col bg-transparent" : `fixed right-0 top-0 h-screen bg-[#12121a]/95 backdrop-blur-xl border-l border-border shadow-2xl transition-all duration-300 z-50 flex flex-col ${isExpanded ? 'w-[800px]' : 'w-[400px]'}`}>
      
      {/* Header */}
      {!overrideVisibility && (
      <div className="p-4 border-b border-border flex items-center justify-between bg-black/20">
        <div className="flex items-center gap-3">
          <div className="bg-gradient-to-br from-blue-500 to-purple-600 p-2 rounded-lg">
            <Bot className="w-5 h-5 text-white" />
          </div>
          <div>
            <h2 className="text-white font-bold">DataPact AI</h2>
            <div className="flex items-center gap-1 text-xs text-muted-foreground mt-0.5">
              <span>Context:</span>
              <span className="flex items-center gap-1 text-blue-400 font-medium">
                {currentContext.icon} {currentContext.label}
              </span>
            </div>
          </div>
        </div>
        
        <div className="flex items-center gap-2">
          <button onClick={() => setIsExpanded(!isExpanded)} className="p-2 hover:bg-secondary rounded-lg text-muted-foreground transition-colors">
            {isExpanded ? <Minimize2 className="w-4 h-4" /> : <Maximize2 className="w-4 h-4" />}
          </button>
        </div>
      </div>
      )}

      {/* Chat History */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">
        {messages.map(msg => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-2xl p-4 ${msg.role === 'user' ? 'bg-blue-600 text-white rounded-br-none' : 'bg-secondary/50 border border-border text-gray-200 rounded-bl-none'}`}>
              <div className="prose prose-invert prose-sm">
                <ReactMarkdown>{msg.content}</ReactMarkdown>
              </div>
              
              {/* Optional Actions */}
              {msg.actions && (
                <div className="mt-4 flex flex-wrap gap-2">
                  {msg.actions.map((action, idx) => (
                    <button key={idx} className="text-xs px-3 py-1.5 bg-blue-500/20 text-blue-400 rounded-lg hover:bg-blue-500/30 transition-colors border border-blue-500/30">
                      {action}
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Prompt Suggestions */}
      <div className="px-4 py-2 flex gap-2 overflow-x-auto custom-scrollbar">
        <button onClick={() => setInput("Explain this incident")} className="flex-shrink-0 text-xs px-3 py-1.5 bg-secondary hover:bg-muted border border-border rounded-full text-muted-foreground transition-colors">
          Explain incident
        </button>
        <button onClick={() => setInput("Generate contract")} className="flex-shrink-0 text-xs px-3 py-1.5 bg-secondary hover:bg-muted border border-border rounded-full text-muted-foreground transition-colors">
          Generate contract
        </button>
        <button onClick={() => setInput("Show affected dashboards")} className="flex-shrink-0 text-xs px-3 py-1.5 bg-secondary hover:bg-muted border border-border rounded-full text-muted-foreground transition-colors">
          Show dashboards
        </button>
      </div>

      {/* Input Area */}
      <div className="p-4 border-t border-border bg-black/20">
        <div className="relative flex items-center">
          <input 
            type="text" 
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSend()}
            placeholder="Ask DataPact AI..."
            className="w-full bg-secondary border border-border rounded-xl pl-4 pr-12 py-3 text-sm text-white focus:outline-none focus:border-blue-500/50 transition-colors"
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim()}
            className="absolute right-2 p-2 bg-blue-600 text-white rounded-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-blue-700 transition-colors"
          >
            <Send className="w-4 h-4" />
          </button>
        </div>
      </div>

    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { Command } from 'cmdk';
import { useAppStore } from '@/store/useAppStore';
import { Database, Shield, Bot, AlertTriangle, FileText, X } from 'lucide-react';
import { useRouter } from 'next/navigation';
import './command-center.css';

export default function CommandCenter() {
  const { isCommandCenterOpen, setCommandCenterOpen } = useAppStore();
  const router = useRouter();
  
  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === 'k' && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        setCommandCenterOpen(!isCommandCenterOpen);
      }
    };
    document.addEventListener('keydown', down);
    return () => document.removeEventListener('keydown', down);
  }, [isCommandCenterOpen, setCommandCenterOpen]);

  if (!isCommandCenterOpen) return null;

  const navigateTo = (path: string) => {
    router.push(path);
    setCommandCenterOpen(false);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center pt-[15vh] bg-black/50 backdrop-blur-sm" onClick={() => setCommandCenterOpen(false)}>
      <div 
        className="w-full max-w-2xl bg-card/80 border border-border shadow-2xl rounded-2xl overflow-hidden glass animate-in fade-in zoom-in-95 duration-200"
        onClick={e => e.stopPropagation()}
      >
        <Command label="Command Menu" className="w-full">
          <div className="flex items-center px-4 py-3 border-b border-border">
            <Command.Input 
              autoFocus 
              placeholder="Search assets, commands, incidents..." 
              className="w-full bg-transparent border-none text-lg outline-none placeholder:text-muted-foreground"
            />
            <button onClick={() => setCommandCenterOpen(false)} className="text-muted-foreground hover:text-foreground">
              <X className="w-5 h-5" />
            </button>
          </div>

          <Command.List className="max-h-[300px] overflow-y-auto p-2">
            <Command.Empty className="py-6 text-center text-sm text-muted-foreground">No results found.</Command.Empty>
            
            <Command.Group heading="Quick Actions" className="px-2 py-1 text-xs font-semibold text-muted-foreground">
              <Command.Item onSelect={() => navigateTo('/ai/contracts')} className="flex items-center gap-2 px-2 py-2 rounded-md hover:bg-muted cursor-pointer text-sm">
                <Bot className="w-4 h-4 text-purple-400" />
                <span>Generate AI Contract</span>
              </Command.Item>
              <Command.Item onSelect={() => navigateTo('/metadata/discovery')} className="flex items-center gap-2 px-2 py-2 rounded-md hover:bg-muted cursor-pointer text-sm">
                <Database className="w-4 h-4 text-blue-400" />
                <span>Scan Metadata</span>
              </Command.Item>
            </Command.Group>

            <Command.Group heading="Navigation" className="px-2 py-1 text-xs font-semibold text-muted-foreground mt-2">
              <Command.Item onSelect={() => navigateTo('/assets')} className="flex items-center gap-2 px-2 py-2 rounded-md hover:bg-muted cursor-pointer text-sm">
                <Database className="w-4 h-4" />
                <span>Asset Catalog</span>
              </Command.Item>
              <Command.Item onSelect={() => navigateTo('/contracts')} className="flex items-center gap-2 px-2 py-2 rounded-md hover:bg-muted cursor-pointer text-sm">
                <Shield className="w-4 h-4" />
                <span>Data Contracts</span>
              </Command.Item>
              <Command.Item onSelect={() => navigateTo('/incidents')} className="flex items-center gap-2 px-2 py-2 rounded-md hover:bg-muted cursor-pointer text-sm">
                <AlertTriangle className="w-4 h-4" />
                <span>Incidents</span>
              </Command.Item>
              <Command.Item onSelect={() => navigateTo('/runbooks')} className="flex items-center gap-2 px-2 py-2 rounded-md hover:bg-muted cursor-pointer text-sm">
                <FileText className="w-4 h-4" />
                <span>Runbooks</span>
              </Command.Item>
            </Command.Group>
          </Command.List>
        </Command>
      </div>
    </div>
  );
}

